create or replace function public.svc_qilt_context(p_survey_code text) returns jsonb language sql security definer set search_path to 'catalogue','ref','public','extensions' as $function$ with survey as (select id,code from ref.outcome_surveys where code=p_survey_code and source_family='QILT' and status='active'),metrics as (select coalesce(jsonb_object_agg(m.code,m.id),'{}'::jsonb) j from ref.outcome_metrics m join survey s on s.id=m.survey_id where m.status='active'),au as (select coalesce(jsonb_agg(jsonb_build_object('id',p.id,'stable_key',p.stable_key,'canonical_name',p.canonical_name,'display_name',p.display_name) order by p.stable_key),'[]'::jsonb) j from catalogue.providers p join ref.countries c on c.id=p.country_id where c.iso_alpha2='AU') select jsonb_build_object('survey_id',(select id from survey),'metric_ids',(select j from metrics),'providers',(select j from au)); $function$;
create or replace function public.svc_qilt_prepare_source(p_survey_code text,p_label text,p_url text,p_collection_version integer) returns uuid language plpgsql security definer set search_path to 'pipeline','ref','public','extensions' as $function$ declare v_id uuid; v_country uuid; begin if not exists(select 1 from ref.outcome_surveys where code=p_survey_code and source_family='QILT') then raise exception 'invalid QILT survey'; end if; select id into v_country from ref.countries where iso_alpha2='AU'; select id into v_id from pipeline.sources where label=p_label and url=p_url limit 1; if v_id is null then insert into pipeline.sources(source_type,country_id,url,label,trust_rank,status,metadata) values('structured_outcomes',v_country,p_url,p_label,95,'active',jsonb_build_object('layer','2A','publisher','QILT','survey_code',p_survey_code,'collection_version',p_collection_version,'identity_authority',false)) returning id into v_id; else update pipeline.sources set source_type='structured_outcomes',country_id=v_country,trust_rank=95,status='active',metadata=coalesce(metadata,'{}'::jsonb)||jsonb_build_object('layer','2A','publisher','QILT','survey_code',p_survey_code,'collection_version',p_collection_version,'identity_authority',false),updated_at=now() where id=v_id; end if; return v_id; end $function$;
create or replace function public.svc_qilt_touch_source(p_source_id uuid,p_ok boolean,p_error text default null) returns void language plpgsql security definer set search_path to 'pipeline','public' as $function$ begin update pipeline.sources set last_checked_at=now(),last_success_at=case when p_ok then now() else last_success_at end,last_failure_at=case when not p_ok then now() else last_failure_at end,last_error=case when p_ok then null else p_error end,updated_at=now() where id=p_source_id; end $function$;
revoke all on function public.svc_qilt_context(text),public.svc_qilt_prepare_source(text,text,text,integer),public.svc_qilt_touch_source(uuid,boolean,text) from public,anon,authenticated; grant execute on function public.svc_qilt_context(text),public.svc_qilt_prepare_source(text,text,text,integer),public.svc_qilt_touch_source(uuid,boolean,text) to service_role;
